  "My packs": "Мои пакеты",
  "Knowledge packs you make from your chats and files — the model reads them when it answers, like the public packs.": "Пакеты знаний из ваших чатов и файлов — модель читает их при ответе, как и открытые пакеты.",
  "No packs yet. Make one from your chats, notes or Markdown files.": "Пакетов пока нет. Сделайте первый из чатов, заметок или файлов Markdown.",
