  "Every part is checked: numbers, names and codes kept exactly.": "Каждая часть проверена: числа, имена и коды сохранены точно.",
  "Open a PDF, Word file, book or web page. Read it here and chat with it — every answer shows the page it came from. Everything stays on your phone.": "Откройте PDF, файл Word, книгу или веб-страницу. Читайте здесь и общайтесь с документом — у каждого ответа указана страница. Всё остаётся на телефоне.",
  "Open a file": "Открыть файл",
  "Reading and searching work now. To chat with the file, install a model in Engine.": "Чтение и поиск уже работают. Чтобы общаться с файлом, установите модель в разделе «Движок».",
  "Your documents appear here": "Здесь появятся ваши документы",
  "Open a file: it is kept on this device, with its chat and notes, so you can come back to it.": "Откройте файл: он сохранится на устройстве вместе с чатом и заметками, и к нему можно вернуться.",
  "Stop": "Стоп",
  "Describe it in one sentence — the AI on your phone writes a designed PowerPoint or a full report, from the web or your own file. Edit any slide, then save it as PowerPoint, Word or PDF.": "Опишите одним предложением — ИИ на телефоне сделает оформленную презентацию PowerPoint или полный отчёт, по данным из сети или вашего файла. Измените любой слайд и сохраните как PowerPoint, Word или PDF.",
  "Presentation": "Презентация",
  "Report": "Отчёт",
  "e.g. A pitch for our café to offices in New Cairo: menu, catering, prices, why us": "напр. Презентация нашего кафе для офисов Нового Каира: меню, кейтеринг, цены, почему мы",
  "Research the web for facts and figures": "Искать факты и цифры в интернете",
  "Each slide names its sources, and a Sources slide lists every page": "У каждого слайда указаны источники, а слайд «Источники» перечисляет все страницы",
  "Base it on my file (Word, PDF, Excel, CSV…)": "На основе моего файла (Word, PDF, Excel, CSV…)",
  "Make the presentation": "Сделать презентацию",
