  "Each slide or section shows here as it is written.": "Каждый слайд или раздел появляется здесь по мере написания.",
  "Build a CV in English or Arabic, keep a copy for every job, and export a clean PDF or Word file. The AI on your phone helps with wording.": "Составьте резюме на английском или арабском, храните копию под каждую вакансию и экспортируйте в аккуратный PDF или Word. ИИ на телефоне поможет с формулировками.",
  "New CV": "Новое резюме",
  "Import my CV": "Импорт резюме",
  "No CVs yet": "Резюме пока нет",
  "Start a new one, or import the one you already have.": "Начните новое или импортируйте уже готовое.",
  "Copy a video's link, paste it here, pick the quality — it's saved to your phone's Movies folder. Works with direct video links, Google Drive, Dropbox, archive.org, Wikimedia Commons and pages that show a plain video.": "Скопируйте ссылку на видео, вставьте сюда, выберите качество — видео сохранится в папку «Фильмы». Работает с прямыми ссылками, Google Drive, Dropbox, archive.org, Wikimedia Commons и страницами с обычным видео.",
  "Find the video": "Найти видео",
  "The video's versions appear here": "Здесь появятся версии видео",
