  "tokens of": "токенов из",
  "fits · {p}% of the window": "помещается · {p}% окна",
  "A quarter of the window is held back for the answer — a prompt that exactly fills the context leaves no room to reply.": "Четверть окна оставлена под ответ — промпт, который заполняет весь контекст, не оставляет места для ответа.",
  "Port context to": "Перенести контекст в",
  "Trim": "Обрезать",
  "AI Compress": "Сжать ИИ",
  "Port": "Перенести",
  "= instant filler removal (offline).": "= мгновенное удаление «воды» (офлайн).",
  "= the model rewrites it far shorter while keeping the meaning.": "= модель переписывает гораздо короче, сохраняя смысл.",
  "Result": "Результат",
  "Paste a wordy prompt and hit": "Вставьте многословный промпт и нажмите",
  "— it thinks about meaning, not just filler words.": "— он думает о смысле, а не только о лишних словах.",
  "Text to rewrite": "Текст для переписывания",
  "Paste AI-generated or stiff text — it comes back sounding like a person wrote it.": "Вставьте текст от ИИ или скованный текст — он вернётся так, будто его написал человек.",
  "Your writing sample": "Пример вашего текста",
  "(this is what makes it sound like you)": "(именно это делает его похожим на вас)",
  "Paste a few paragraphs you wrote yourself — an email, a message, anything in your natural voice.": "Вставьте пару абзацев, написанных вами — письмо, сообщение, что угодно вашим обычным языком.",
  "Keeps your meaning and facts exactly — changes only how it reads. The writing sample is optional but makes the biggest difference.": "Смысл и факты сохраняются точно — меняется только звучание. Пример текста необязателен, но именно он даёт главный эффект.",
  "Rewritten": "Переписано",
  "Paste stiff or AI-sounding text, add a sample of your own writing, and it comes back in your voice — same meaning, human rhythm.": "Вставьте скованный или «нейросетевой» текст, добавьте пример своего письма — и он вернётся вашим голосом: тот же смысл, живой ритм.",
  "Chat through Attune — it reads the whole conversation and sharpens every next prompt.": "Общайтесь через Attune — он читает весь разговор и улучшает каждый следующий промпт.",
  "What do you want out of this whole conversation? (optional, but it makes every prompt better)": "Чего вы хотите от всего этого разговора? (необязательно, но так каждый промпт лучше)",
  "Bring the chat from {t} — paste the whole conversation or just its last reply:": "Перенесите чат из {t} — вставьте весь разговор или только последний ответ:",
  "Paste here…": "Вставьте сюда…",
  "Read it & suggest my reply": "Прочитать и предложить ответ",
  "What do you want to ask? Type it however you like.": "Что хотите спросить? Пишите как удобно.",
  "Optimize my prompt": "Улучшить мой промпт",
  "The loop: type intent → get an optimized prompt → send it → bring the reply back → each next prompt is sharper. In the phone app, the share-sheet replaces copy-paste entirely.": "Цикл: пишете цель → получаете улучшенный промпт → отправляете → возвращаете ответ → каждый следующий промпт точнее. В приложении на телефоне меню «Поделиться» полностью заменяет копирование.",
  "Ready prompt recipes — pick one, fill the blanks, then": "Готовые рецепты промптов — выберите, заполните пропуски, затем",
  "to tailor it.": "чтобы подогнать под себя.",
  "· check updates": "· проверить обновления",
  "Writing & Email": "Тексты и письма",
  "Business & Work": "Бизнес и работа",
  "Study & Research": "Учёба и исследования",
  "Coding": "Программирование",
  "Everyday": "Повседневное",
  "Personal & Life": "Личное и жизнь",
  "Power Techniques": "Продвинутые приёмы",
  "Polish an email": "Отшлифовать письмо",
  "Refines fluency, keeps your meaning": "Делает текст глаже, сохраняя смысл",
  "Explicit action verbs beat vague asks (Anthropic 2026)": "Чёткие глаголы действия лучше размытых просьб (Anthropic 2026)",
  "Use recipe": "Взять рецепт",
  "Reply to a hard message": "Ответить на трудное сообщение",
  "Calm, firm, keeps the relationship": "Спокойно, твёрдо, без ссоры",
  "State the desired outcome, not steps (OpenAI 2026)": "Описывайте желаемый результат, а не шаги (OpenAI 2026)",
  "Shorten without losing meaning": "Сократить без потери смысла",
  "Cuts length, keeps every point": "Короче, но все мысли на месте",
  "Concise prompts cut cost ~76% and lift quality": "Краткие промпты снижают стоимость ~на 76% и повышают качество",
  "Rewrite in my own voice": "Переписать моим голосом",
  "Matches how you actually write": "Как вы на самом деле пишете",
  "Style examples outperform adjectives like 'professional'": "Примеры стиля работают лучше прилагательных вроде «профессионально»",
  "Fix tone without changing content": "Поправить тон, не меняя сути",
  "Same substance, better delivery": "Та же суть, лучше подача",
  "Scoping the edit prevents unwanted rewrites": "Чёткие рамки правки защищают от лишних переписываний",
