  "Run the AI on your own hardware. Nothing leaves the device, nothing costs per use.": "Запускайте ИИ на своём железе. Ничего не уходит с устройства, никакой платы за использование.",
  "Runs smoothly on a 12 GB phone: expert answers, and the best at reading documents and photos.": "Плавно работает на телефоне с 12 ГБ: экспертные ответы и лучшее чтение документов и фото.",
