  "Core Max, Sense, Zenith, Apex and Everest run on a computer: get them in the Attune desktop app.": "Core Max, Sense, Zenith, Apex и Everest работают на компьютере: они есть в настольном приложении Attune.",
  "Too heavy for a phone — it can close the app. Core or Blaze run smoothly here; this one is in the desktop app.": "Слишком тяжёлая для телефона — приложение может закрыться. Здесь плавно работают Core или Blaze; эта модель — в настольном приложении.",
