  "This model is large for this phone. It works, but answers come slowly and the phone gets warm. For quick, smooth answers use Qwen 3.5 4B — same Arabic, reads photos, about 3× faster.": "Эта модель велика для этого телефона. Она работает, но ответы идут медленно, а телефон греется. Для быстрых и плавных ответов выберите Qwen 3.5 4B — тот же уровень арабского, читает фото, примерно в 3 раза быстрее.",
