  "Installed weights never update on their own, so a prompt that works today works the same way in a year. The fingerprint proves exactly which file is answering.": "Установленные веса никогда не обновляются сами, поэтому запрос, который работает сегодня, через год сработает так же. Отпечаток точно показывает, какой файл отвечает.",
