  "Any GGUF on Hugging Face as": "Любой GGUF с Hugging Face в виде",
  ", or a direct https link. Specialist and fine-tuned models install the same way — the photo reader is fetched too when the repo has one.": ", или прямая ссылка https. Специализированные и дообученные модели устанавливаются так же — если в репозитории есть модуль чтения фото, он тоже загрузится.",
  "How it answers": "Как отвечать",
  "e.g. I run a small shop in Egypt. Answer in Egyptian Arabic unless I write in English. Give prices in EGP.": "напр. У меня небольшой магазин в Египте. Отвечай по-египетски на арабском, если я не пишу по-английски. Цены указывай в EGP.",
  "Saved when you tap outside the box. Stays on this phone.": "Сохраняется, когда вы нажимаете за пределами поля. Остаётся на этом телефоне.",
  "Web lookup": "Поиск в интернете",
  "Only the question you look up and the pages opened leave the phone — never your conversation, files or memory.": "С телефона уходят только ваш поисковый запрос и открытые страницы — никогда переписка, файлы или память.",
  "Hide network log": "Скрыть журнал сети",
  "made ·": "выполнено ·",
  "blocked · this session": "заблокировано · за этот сеанс",
  "Nothing has left the phone.": "Ничего не покидало телефон.",
  "The model itself never uses the network. The log lists every connection the app made or refused, host and reason only — the proof behind \"nothing leaves this phone\".": "Сама модель никогда не использует сеть. В журнале — каждое соединение, которое приложение выполнило или отклонило: только хост и причина. Это доказательство того, что «ничто не покидает телефон».",
  "Load a model to start": "Загрузите модель, чтобы начать",
