  "Parity: unverified until this tier passes its eval set — ✓ appears only after it does.": "Паритет: не подтверждён, пока этот уровень не пройдёт набор проверок — ✓ появится только после этого.",
  "Needs": "Нужно",
  "GB RAM": "ГБ ОЗУ",
  " · desktop or laptop": " · компьютер или ноутбук",
  "Working memory": "Рабочая память",
