  "KV": "KV",
  "% cache": "% кэша",
  "GB total": "ГБ всего",
  "INT4 KV cache + sliding-window eviction, so long conversations don't grow unbounded.": "Кэш KV в INT4 и вытеснение по скользящему окну, чтобы длинные разговоры не росли без границ.",
  "Storage:": "Хранилище:",
  "Compute": "Вычисления",
  "Prefill runs where compute is fastest, decode where bandwidth is. Using both raises usable bandwidth ~43 → 59 GB/s.": "Prefill идёт там, где вычисления быстрее всего, decode — там, где выше пропускная способность. Вместе они поднимают доступную пропускную способность с ~43 до 59 ГБ/с.",
  "Task adapters": "Адаптеры задач",
  "Small fine-tunes for each job — this is what makes a phone-sized model punch above its weight. Loaded over the base model, a few MB each.": "Небольшие дообучения под каждую задачу — именно они позволяют модели размером с телефон работать лучше своего веса. Подключаются к базовой модели, по несколько МБ каждый.",
  "MB": "МБ",
  " · ready": " · готово",
  "No training pairs yet": "Пар для обучения пока нет",
  "Training set exported": "Обучающий набор экспортирован",
  "No eval pairs yet": "Пар для проверки пока нет",
  "Eval set exported": "Проверочный набор экспортирован",
  "Training data cleared": "Данные для обучения очищены",
  "pairs per feature before a tier can be judged. ~": "пар на функцию, прежде чем можно оценить уровень. ~",
  "% is held back and never trained on, so the test stays honest.": "% откладывается и никогда не используется для обучения, поэтому проверка остаётся честной.",
  "Where it runs": "Где работает",
  "Loading the model into memory — large models take a minute": "Модель загружается в память — большим моделям нужна минута",
  "Model": "Модель",
  "loaded — running locally": "загружена — работает на устройстве",
  "Downloading model…": "Загрузка модели…",
  "No model fits this device": "Ни одна модель не подходит для этого устройства",
  "Your real names for your real things. Every document then uses them correctly — no invented equipment names, no wrong site spellings. Stays on your devices.": "Ваши настоящие названия для ваших настоящих вещей. Тогда каждый документ будет использовать их правильно — без выдуманных названий техники и неверного написания объектов. Остаётся на ваших устройствах.",
  "Use company terminology": "Использовать терминологию компании",
  "Company name": "Название компании",
  "e.g. Adrighem & Aldibiki": "напр. Adrighem & Aldibiki",
  "Sites / locations": "Объекты / места",
  "e.g. North Gate Yard, October Depot, Site B — Sheikh Zayed": "напр. North Gate Yard, October Depot, Site B — Sheikh Zayed",
  "Equipment / assets": "Техника / активы",
  "e.g. LTM 1200 (unit 3), Demag AC 100, XCMG QY50KA — 'Crane 3' means unit 3": "напр. LTM 1200 (unit 3), Demag AC 100, XCMG QY50KA — 'Crane 3' означает unit 3",
  "Internal terms & abbreviations": "Внутренние термины и сокращения",
  "e.g. PTW = permit to work, 'the yard' = North Gate, LO = lift operation": "напр. PTW = разрешение на работу, 'the yard' = North Gate, LO = подъёмная операция",
  "Downtime cost / hour": "Стоимость простоя в час",
  "Currency": "Валюта",
  "EGP": "EGP",
  "Turns logged downtime into a figure you can put in front of management.": "Превращает записанные простои в цифру, которую можно показать руководству.",
  "Reporting rules": "Правила отчётности",
  "e.g. every incident must state whether work was stopped; always record permit number": "напр. в каждом инциденте указывать, останавливались ли работы; всегда записывать номер разрешения",
  "This is added to every field document — and it's also what your own adapter trains on, so the model learns your operation, not a generic one.": "Это добавляется в каждый рабочий документ — и на этом же обучается ваш адаптер, так что модель изучает именно вашу работу, а не обобщённую.",
  "Company terminology saved": "Терминология компании сохранена",
  "Site memory": "Память объекта",
  "Every record stays on this device. The connections between them are what a single report can never show you.": "Все записи остаются на этом устройстве. Связи между ними — то, чего не покажет ни один отдельный отчёт.",
