  "challenge the answer and make it defend or correct itself": "оспорьте ответ и заставьте его защитить или исправить себя",
  "Reads clean structure well — tags mark where context ends and the task begins.": "Хорошо читает чёткую структуру — теги отмечают, где кончается контекст и начинается задача.",
  "Turn on Extended Thinking for hard reasoning.": "Включите расширенное мышление для сложных рассуждений.",
  "Does best when you name the outcome and let it choose the path.": "Лучше всего работает, когда вы называете результат и даёте выбрать путь самому.",
  "Let the router pick, or choose Thinking for complex tasks.": "Пусть маршрутизатор выберет сам или выберите режим «Мышление» для сложных задач.",
  "Wants direct, concise input and defaults to short answers.": "Любит прямой и краткий ввод, по умолчанию отвечает коротко.",
  "Use Pro; enable Deep Research for multi-source work.": "Используйте Pro; включите Deep Research для работы с несколькими источниками.",
  "Handles direct, conversational prompts; ask for reasoning explicitly.": "Хорошо справляется с прямыми разговорными запросами; просите рассуждения явно.",
  "Turn on Think mode for step-by-step reasoning.": "Включите режим Think для пошаговых рассуждений.",
