  "3 templates · 5 history items": "3 шаблона · 5 записей в истории",
  "35B of knowledge, 3B doing the work on each token — near-frontier answers at a speed a laptop can sustain. A mixture-of-experts model keeps every expert in memory even though few run per token, so this needs the RAM of a 35B and the compute of a 3B.": "35B знаний, из которых на каждый токен работают 3B — ответы почти уровня топовых моделей со скоростью, доступной ноутбуку. Модель со смесью экспертов держит всех экспертов в памяти, хотя на токен работают лишь немногие, так что ей нужна ОЗУ как у 35B, а вычисления как у 3B.",
  "A bigger length budget for reports, plans and analysis.": "Больший лимит длины для отчётов, планов и анализа.",
