  "Documents, fleet records, copilot, every domain pack": "Документы, записи автопарка, копилот, все тематические пакеты",
  "Small enough to download on mobile data if you need to.": "Достаточно небольшая, чтобы при необходимости скачать по мобильному интернету.",
  "This is a large model for a phone. It will run, and it will slow down noticeably once the phone gets warm — keep answers short, or pick the smaller one.": "Это крупная модель для телефона. Она запустится, но заметно замедлится, когда телефон нагреется, — отвечайте коротко или выберите модель поменьше.",
  "Every tool, and all 31 country packs": "Все инструменты и все 31 пакет стран",
  "Finds what you promised people, from your own words": "Находит то, что вы кому-то обещали, по вашим собственным словам",
  "Fixed randomness, so a workflow gives identical output every time it runs.": "Фиксированная случайность: рабочий процесс при каждом запуске даёт одинаковый результат.",
  "Free web search: DuckDuckGo, Bing and Mojeek at once, then the top pages are read in full, so answers come from real passages.": "Бесплатный веб-поиск: DuckDuckGo, Bing и Mojeek одновременно, затем лучшие страницы читаются целиком, так что ответы основаны на реальных отрывках.",
  "Free · no key": "Бесплатно · без ключа",
