  "No account, no sign-in, nothing uploaded": "Без аккаунта, без входа, ничего не загружается",
  "Running": "Работает",
  "Loading the model…": "Загрузка модели…",
  "Nothing in the app can reach the internet — no web lookup, no maps, no downloads. The model and everything on the phone keep working.": "Ничто в приложении не имеет доступа к интернету — ни поиска, ни карт, ни загрузок. Модель и всё на телефоне продолжают работать.",
  "The model reasons first on every question. Clearly better on hard problems, but on a phone the answer starts 30–90 s later. Off: tap “Think” on just the questions that need it.": "Модель сначала рассуждает над каждым вопросом. Заметно лучше на сложных задачах, но на телефоне ответ начинается на 30–90 с позже. Выключено: нажимайте «Думать» только на тех вопросах, где это нужно.",
  "The same model as below, given the memory to hold a whole book of context at once. On a 48 GB machine the spare RAM is better spent on context than on precision — you can hand it an entire contract or a year of notes and it keeps all of it in view.": "Та же модель, что ниже, но с памятью, чтобы удерживать контекст размером с целую книгу. На машине с 48 ГБ запас ОЗУ лучше потратить на контекст, чем на точность — можно отдать ей целый договор или год заметок, и она будет держать всё в поле зрения.",
  "The whole assistant, on your device": "Весь ассистент на вашем устройстве",
