  "Starting the picture engine…": "Запуск движка картинок…",
  "Studio works in the Android app.": "Studio работает в приложении для Android.",
  "The chat model was paused to make room, and is loading again.": "Чат-модель приостановлена, чтобы освободить место, и загружается снова.",
  "This APK has no picture engine yet — it comes with the next APK built on GitHub.": "В этом APK ещё нет движка картинок — он появится в следующем APK, собранном на GitHub.",
  "This build draws on the CPU.": "Эта сборка рисует на CPU.",
