  "This version of Attune has no graphics-chip picture engine, so pictures are drawn on the CPU (slower). An update adds it.": "В этой версии Attune нет движка картинок на графическом чипе, поэтому картинки рисуются на CPU (медленнее). Обновление его добавит.",
  "The picture engine stopped responding while loading the model, so it was stopped. Engine → Engine log shows its last lines — send them to support.": "Движок картинок перестал отвечать при загрузке модели, поэтому его остановили. В «Движок» → «Журнал движка» видны его последние строки — отправьте их в поддержку.",
  "This phone's GPU driver did not answer, so pictures are drawn on the CPU (slower).": "Драйвер GPU этого телефона не ответил, поэтому картинки рисуются на CPU (медленнее).",
  "What should change? e.g. “make it night, with the street lights on”": "Что изменить? напр. «сделай ночь, с зажжёнными фонарями»",
