  "None yet — add a field of type “Link to another table”, or ask below: “connect Jobs to Customers”.": "Пока нет — добавьте поле типа «Связь с другой таблицей» или спросите ниже: «свяжи Заказы с Клиентами».",
  "Count": "Количество",
  "No records match": "Подходящих записей нет",
  "Ask your data — like an Access query, in words": "Спросите свои данные — как запрос в Access, только словами",
  "e.g. unpaid invoices over 50,000 · jobs this month by customer · top 5 cranes by revenue": "напр. неоплаченные счета свыше 50 000 · заказы этого месяца по клиентам · 5 лучших кранов по выручке",
  "Load a model to ask your data in words.": "Загрузите модель, чтобы спрашивать свои данные словами.",
  "Query saved": "Запрос сохранён",
  "Save query": "Сохранить запрос",
  "Saved queries": "Сохранённые запросы",
  "Describe a form — the fields to fill, in order": "Опишите форму — какие поля заполнять и в каком порядке",
  "e.g. a quick job form for the site: customer, crane, start date, days — status New": "напр. быстрая форма заказа на объекте: клиент, кран, дата начала, дни — статус «Новый»",
  "Make the form": "Создать форму",
  "Load a model to make forms in words.": "Загрузите модель, чтобы создавать формы словами.",
  "Form saved — pick it above the records when you add one": "Форма сохранена — выберите её над записями, когда будете добавлять запись",
  "Save form": "Сохранить форму",
  "No forms yet. A form shows only the fields you need, in your order, with ready values — pick it when you add a record.": "Форм пока нет. Форма показывает только нужные вам поля в вашем порядке с готовыми значениями — выберите её при добавлении записи.",
  "Pasted from {t}": "Вставлено из {t}",
  "Copy & open {t}": "Копировать и открыть {t}",
  "Queries": "Запросы",
  "Forms": "Формы",
  "Open an app file (made with Attune)": "Открыть файл приложения (созданный в Attune)",
  "That file isn't an app made with Attune Business.": "Этот файл — не приложение, созданное в Attune Business.",
  "Updated from the app file — {n} tables with their records": "Обновлено из файла приложения — таблиц с записями: {n}",
  "Opened — {n} tables with their records": "Открыто — таблиц с записями: {n}",
  "Change the design in words — add fields to any table, new tables, links…": "Измените проект словами — добавляйте поля в любую таблицу, новые таблицы, связи…",
  "e.g. add Email and Tax ID to Suppliers, and a Warranty months field to Parts": "напр. добавь Email и ИНН в Поставщики, а в Запчасти — поле «Гарантия, мес.»",
  "Saved — send this file; it opens in any browser, no Attune needed": "Сохранено — отправьте этот файл; он открывается в любом браузере, Attune не нужен",
  "Excel files need Python, which isn't in this build — use CSV.": "Файлам Excel нужен Python, которого нет в этой сборке — используйте CSV.",
  "Making the Excel file…": "Создаю файл Excel…",
  "Couldn't make the Excel file: {e}": "Не удалось создать файл Excel: {e}",
  "Give it to your team as an app: one file with all the data inside — it opens in any phone or computer browser, no Attune needed. When something needs changing, open the file here (Business → Open an app file), ask the AI, and send the new app back.": "Передайте его команде как приложение: один файл со всеми данными — открывается в браузере любого телефона или компьютера, Attune не нужен. Когда нужно что-то изменить, откройте файл здесь («Бизнес» → «Открыть файл приложения»), попросите ИИ и отправьте новое приложение обратно.",
  "Export as an app": "Экспортировать как приложение",
  "Excel workbook (all tables)": "Книга Excel (все таблицы)",
  "The picture engine stopped before the picture was finished — Android may have closed it to free memory. Try “Quick draft”, or close other apps and try again.": "Движок картинок остановился, не закончив картинку — возможно, Android закрыл его, чтобы освободить память. Попробуйте «Быстрый черновик» или закройте другие приложения и повторите.",
  "The picture could not be made. Open Engine → Engine log and send me what it says.": "Картинку не удалось создать. Откройте «Движок» → «Журнал движка» и отправьте мне, что там написано.",
  "Multi-token prediction (faster writing)": "Многотокенное предсказание (быстрее пишет)",
  "Off by default: on some phones it doubles words and digits (“ItIt is is”, “20205”). Turn it on only if answers stay correct.": "По умолчанию выключено: на некоторых телефонах удваивает слова и цифры («ItIt is is», «20205»). Включайте, только если ответы остаются верными.",
  "The last picture didn't finish:": "Последняя картинка не завершилась:",
  "Connected {n} fields to their tables": "Поля связаны с таблицами: {n}",
  "Connect the tables for me ({n})": "Связать таблицы за меня ({n})",
  "Connected {n} fields — Undo (top) puts them back": "Связано полей: {n} — «Отменить» (вверху) вернёт всё как было",
  "Connect the tables": "Связать таблицы",
  "Something went wrong on this screen.": "На этом экране что-то пошло не так.",
  "Your chats and data are safe. Try again — if it keeps happening, send me this message.": "Ваши чаты и данные в безопасности. Попробуйте ещё раз — если повторяется, отправьте мне это сообщение.",
  "Try again": "Повторить",
  "Reading page {i} of {n} — {t}": "Читаю страницу {i} из {n} — {t}",
  "Checking what is still missing…": "Проверяю, чего ещё не хватает…",
  "Searching again for: {q}": "Ищу снова: {q}",
  "Searching again for: {what}…": "Ищу снова: {what}…",
  "Writing the full answer from {n} pages…": "Пишу полный ответ по страницам: {n}…",
  "read {p} pages one by one, facts from {n}": "прочитано страниц по одной: {p}, факты из: {n}",
  "Checking the picture engine and model files…": "Проверяю движок картинок и файлы модели…",
  "Short of memory — drawing it smaller (512 px)…": "Не хватает памяти — рисую меньше (512 px)…",
  "Basic": "Базовый",
  "Quick tidy-ups, short answers": "Быстрые правки, короткие ответы",
