  "The model took too long on this question — try a shorter one, or a faster model in Engine.": "Модель слишком долго думала над этим вопросом — попробуйте покороче или выберите модель побыстрее в «Движок».",
  "Reading your CV… the AI is sorting it into sections": "Читаю ваше резюме… ИИ раскладывает его по разделам",
  "Imported — check each section and fix anything": "Импортировано — проверьте каждый раздел и поправьте, если нужно",
