  "Connecting…": "Подключение…",
  "The download stopped moving. Check the connection and tap Download — it continues where it stopped.": "Загрузка остановилась. Проверьте соединение и нажмите «Скачать» — она продолжится с того же места.",
  "Download maps": "Скачать карты",
  "Update ready": "Есть обновление",
  "Search a place and tap “Save this place” — saved places work with no signal.": "Найдите место и нажмите «Сохранить это место» — сохранённые места работают без сети.",
  "Download a whole country once: every road, building, place and shop, and search — all with no signal. A new version is built every week from OpenStreetMap; the app tells you when one is ready.": "Скачайте страну целиком один раз: все дороги, здания, места и магазины, а также поиск — всё без сети. Новая версия собирается каждую неделю из OpenStreetMap; приложение сообщит, когда она готова.",
  "On this phone · data of {d} · {s}": "На этом телефоне · данные от {d} · {s}",
  "showing": "показана",
  "{s} · data of {d}": "{s} · данные от {d}",
  "Pause": "Пауза",
  "Update": "Обновить",
  "The world map isn't published yet.": "Карта мира ещё не опубликована.",
  "Download the world map? {s} — every country, without street detail.": "Скачать карту мира? {s} — все страны, без детализации улиц.",
  "online map": "онлайн-карта",
  "showing online": "показана онлайн",
  "Around {p}": "Рядом: {p}",
  "Read by AI: {s}": "Прочитано ИИ: {s}",
  "With signal, every country here shows online without downloading — every street, compound and place. Download only to use it with no signal.": "При наличии сети любая страна здесь показывается онлайн без загрузки — каждая улица, жилой комплекс и место. Скачивайте, только чтобы пользоваться без сети.",
  "This map is not published yet": "Эта карта ещё не опубликована",
  "Offline maps work in the Android app.": "Офлайн-карты работают в приложении для Android.",
  "This country's map isn't published yet — it is built every Friday.": "Карта этой страны ещё не опубликована — их собирают каждую пятницу.",
  "Update the map of {c} to the data of {d}? {s} — on Wi-Fi is best. The old map works until the new one is ready.": "Обновить карту ({c}) до данных от {d}? {s} — лучше по Wi-Fi. Старая карта работает, пока новая не готова.",
  "Download the whole map of {c}? {s} — on Wi-Fi is best. Every road, building, place and shop, and offline search.": "Скачать всю карту ({c})? {s} — лучше по Wi-Fi. Все дороги, здания, места и магазины и офлайн-поиск.",
  "Map updated": "Карта обновлена",
  "The map of {c} works offline now": "Карта ({c}) теперь работает офлайн",
