  "Free 30-day visa on arrival for every nationality, with a confirmed booking and a return ticket.": "Бесплатная виза по прибытии на 30 дней для любого гражданства при подтверждённой брони и обратном билете.",
  "Every visitor needs an approved eTA online before flying.": "Каждому путешественнику нужен одобренный онлайн eTA до вылета.",
  "Free movement (Switzerland is in Schengen).": "Свобода передвижения (Швейцария входит в Шенген).",
  "Visa-free 90 days in 180 (Schengen area); ETIAS once it launches.": "Без визы 90 дней из 180 (Шенгенская зона); ETIAS после запуска.",
  "Cyprus visa required (Cyprus is in the EU but not in Schengen). Holders of a valid Schengen double or multiple-entry visa can often enter — confirm with the embassy.": "Нужна кипрская виза (Кипр в ЕС, но не в Шенгене). Владельцы действующей двукратной или многократной шенгенской визы часто могут въехать — уточните в посольстве.",
  "Depends on nationality; a valid Schengen visa often allows entry — check.": "Зависит от гражданства; действующая шенгенская виза часто позволяет въезд — уточните.",
  "US visa (B1/B2) required — apply early; interview waits can be long.": "Нужна виза США (B1/B2) — подавайте заранее; ожидание собеседования может быть долгим.",
  "US visa required.": "Нужна виза США.",
  "ESTA online for Visa Waiver Program countries (most EU).": "ESTA онлайн для стран программы безвизового въезда (большинство стран ЕС).",
  "UK and Australia: ESTA online. Canadians need no visa or ESTA for a visit.": "Великобритания и Австралия: ESTA онлайн. Канадцам для визита не нужны ни виза, ни ESTA.",
  "Umrah or Hajj needs a permit through the Nusuk app, not a tourist visa alone": "Для умры или хаджа нужно разрешение через приложение Nusuk, одной туристической визы мало",
  "Mandatory health insurance is bundled into the e-Visa fee": "Обязательная медицинская страховка входит в сбор за электронную визу",
  "Sponsor or hotel booking is normally required for the application": "Для заявки обычно нужен спонсор или бронь отеля",
  "Israeli stamps or an Israeli passport mean refusal of entry": "Израильские штампы или израильский паспорт — отказ во въезде",
  "Without one of those visas, apply through an Omani mission": "Без одной из этих виз подавайте через представительство Омана",
  "The Jordan Pass waives the visa fee AND covers Petra — buy it before you fly": "Jordan Pass отменяет визовый сбор И включает Петру — купите его до вылета",
  "Confirmed hotel reservation": "Подтверждённая бронь отеля",
  "Around US$2,000 in cash to show": "Около 2000 US$ наличными, чтобы показать",
  "Return ticket": "Обратный билет",
  "No Israeli stamps anywhere in the passport": "Никаких израильских штампов в паспорте",
  "This age rule catches people out — check it before booking": "Это возрастное правило многих подводит — проверьте до бронирования",
  "The digital arrival card (MDAC) must be completed online within 3 days before arrival": "Электронную карту прибытия (MDAC) нужно заполнить онлайн в течение 3 дней до прибытия",
  "Complete the MDAC digital arrival card online": "Заполните электронную карту прибытия MDAC онлайн",
  "Some transit exemptions exist at major airports": "В крупных аэропортах есть некоторые исключения для транзита",
  "Must be applied for through an authorised agent or the ICA": "Подавать нужно через уполномоченного агента или ICA",
  "Bank statements and evidence of ties to your home country are normally required": "Обычно нужны банковские выписки и подтверждение связей с родной страной",
  "Travel insurance covering €30,000 of medical costs": "Туристическая страховка с покрытием медицинских расходов на €30 000",
