  "Insurance covering €30,000": "Страховка с покрытием €30 000",
  "Bank statements and proof of ties to Egypt": "Банковские выписки и подтверждение связей с Египтом",
  "Complete the IMUGA traveller declaration online within 96 hours before arrival": "Заполните декларацию путешественника IMUGA онлайн в течение 96 часов до прибытия",
  "Evidence of ties to Egypt: job, property, family, bank statements": "Подтверждение связей с Египтом: работа, недвижимость, семья, банковские выписки",
  "Use the official ESTA website only": "Пользуйтесь только официальным сайтом ESTA",
  "For Umrah or Hajj: the permit is issued through the Nusuk app, separately from the visa": "Для умры или хаджа разрешение выдаётся через приложение Nusuk отдельно от визы",
  "Children under 18 need an unabridged birth certificate showing both parents": "Детям до 18 лет нужно полное свидетельство о рождении с указанием обоих родителей",
  "The e-Visa must be printed or saved — airlines ask to see it at check-in": "Электронную визу нужно распечатать или сохранить — авиакомпании просят показать её при регистрации",
  "If you are not staying in a hotel, register your address with the local police within 24 hours": "Если вы живёте не в отеле, зарегистрируйте адрес в местной полиции в течение 24 часов",
  "Check the banned-medicines list before flying — some common cold and allergy tablets are prohibited": "Перед вылетом проверьте список запрещённых лекарств — некоторые обычные таблетки от простуды и аллергии запрещены",
  "An SG Arrival Card must be submitted online within 3 days before arrival": "Карту прибытия SG Arrival Card нужно подать онлайн в течение 3 дней до прибытия",
  "The MDAC digital arrival card must be submitted online before arrival": "Электронную карту прибытия MDAC нужно подать онлайн до прибытия",
  "A digital arrival card is being phased in — check before you fly": "Постепенно вводится электронная карта прибытия — проверьте перед вылетом",
  "Carry evidence of onward travel and accommodation; UK border officers do ask": "Имейте подтверждение дальнейшей поездки и жилья; британские пограничники действительно спрашивают",
  "No visa needed": "Виза не нужна",
