  "Visa required in advance": "Виза оформляется заранее",
  "Passport valid at least 6 months beyond your arrival date": "Паспорт действителен минимум 6 месяцев после даты прибытия",
  "A return or onward ticket — airlines check this at check-in, not just immigration": "Обратный или дальнейший билет — авиакомпании проверяют его при регистрации, а не только на границе",
  "Proof of where you're staying (hotel booking or a host's address)": "Подтверждение жилья (бронь отеля или адрес принимающей стороны)",
