  "Told how many days before?": "За сколько дней предупредили?",
  "Hours late at arrival": "Опоздание по прибытии, часов",
  "Passengers": "Пассажиры",
  "The reason they gave": "Причина, которую назвали",
  "You are owed": "Вам положено",
  "You are probably owed": "Вам, скорее всего, положено",
  "per passenger": "на пассажира",
  "Ask the airline for the reason: weather or an air-traffic strike would cancel it; a technical fault or crew shortage would not.": "Спросите у авиакомпании причину: погода или забастовка авиадиспетчеров освобождают её от выплаты, а техническая неисправность или нехватка экипажа — нет.",
  "Write the claim": "Составить претензию",
  "No compensation": "Компенсация не положена",
  "Worked out from the published rules (EU 261, UK 261, Canada's APPR). Airlines sometimes refuse at first — a polite second letter or the national enforcement body usually settles it.": "Рассчитано по опубликованным правилам (EU 261, UK 261, канадские APPR). Авиакомпании иногда сначала отказывают — вежливое повторное письмо или национальный надзорный орган обычно решают вопрос.",
  "What you're owed": "Что вам положено",
