  "What happened — a delay, a cancellation, or you were refused boarding?": "Что случилось — задержка, отмена или вам отказали в посадке?",
  "How late did you ARRIVE (hours)?": "На сколько часов вы опоздали к ПРИБЫТИЮ?",
  "How many days before the flight were you told?": "За сколько дней до рейса вам сообщили?",
  "Was the airline a European one? (EU rules cover flights INTO Europe only on European airlines)": "Авиакомпания была европейской? (правила ЕС распространяются на рейсы В Европу только у европейских авиакомпаний)",
  "Was the airline a UK one? (UK rules cover flights INTO the UK only on UK airlines)": "Авиакомпания была британской? (правила Великобритании распространяются на рейсы В Великобританию только у британских авиакомпаний)",
  "Which airline was it? (Canada's amounts depend on its size)": "Какая это была авиакомпания? (суммы в Канаде зависят от её размера)",
  "How late did you arrive at your destination (hours)?": "На сколько часов вы опоздали в пункт назначения?",
  "Over 3,500 km with a 3–4 hour delay: the airline may halve it.": "Более 3500 км и задержка 3–4 часа: авиакомпания может уменьшить сумму вдвое.",
  "Told 7–13 days ahead: not owed if they offered a flight leaving at most 2 h earlier and arriving at most 4 h later than yours.": "Предупредили за 7–13 дней: не положено, если предложили рейс, вылетающий не более чем на 2 ч раньше и прилетающий не более чем на 4 ч позже вашего.",
  "Told under 7 days ahead: not owed only if they offered a flight leaving at most 1 h earlier and arriving at most 2 h later than yours.": "Предупредили менее чем за 7 дней: не положено, только если предложили рейс, вылетающий не более чем на 1 ч раньше и прилетающий не более чем на 2 ч позже вашего.",
  "Owed when the delay was within the airline's control and not for safety. Claim within 1 year.": "Положено, если задержка зависела от авиакомпании и не была связана с безопасностью. Подайте претензию в течение 1 года.",
  "A delayed or cancelled flight — the airline may owe you money": "Рейс задержан или отменён — авиакомпания может быть должна вам деньги",
  "Return request": "Запрос на возврат",
