  "Android does this for apps installed from a file instead of Google Play. In App info tap ⋮ (top right) → Allow restricted settings, then turn Attune on here again.": "Android так делает с приложениями, установленными из файла, а не из Google Play. В «О приложении» нажмите ⋮ (вверху справа) → «Разрешить ограниченные настройки», затем снова включите Attune здесь.",
