  "Use the NPU (experimental)": "Использовать NPU (экспериментально)",
  "Running on the NPU ({d}).": "Работает на NPU ({d}).",
  "Runs the model on the Snapdragon NPU (Hexagon): much cooler, often faster at reading. Works best with Core Max (8-bit). Switches itself back to the CPU if anything goes wrong.": "Запускает модель на NPU Snapdragon (Hexagon): телефон гораздо холоднее, чтение часто быстрее. Лучше всего с Core Max (8-bit). Сам возвращается на CPU, если что-то пошло не так.",
  "This phone's NPU could not be used by the engine — Attune stays on the CPU.": "Движок не смог использовать NPU этого телефона — Attune остаётся на CPU.",
  "Last time, starting on the NPU closed the app. Attune is back on the CPU; you can try it again in Engine → Speed.": "В прошлый раз запуск на NPU закрыл приложение. Attune снова на CPU; попробовать ещё раз можно в Движок → Скорость.",
  "You have {b}. Until {d} ({n} days) these are due: {t}. What is left, shared over the days, is what you can spend each day.": "У вас {b}. До {d} ({n} дн.) нужно оплатить: {t}. Остаток, поделённый на дни, — это то, что можно тратить в день.",
  "Nothing due before then.": "До этого платить нечего.",
  "Tip: add your salary as a repeating income in Money, and this counts until payday.": "Совет: добавьте зарплату как регулярный доход в «Деньгах», и расчёт будет идти до дня зарплаты.",
  "Keep aside": "Отложить",
