  "about {x} a day until {d}": "около {x} в день до {d}",
  "Safe to spend today": "Можно потратить сегодня",
  "In today's money": "В сегодняшних деньгах",
  "Installments are cheaper in real money by {x}: keep the cash in the bank and pay monthly from it.": "Рассрочка дешевле в реальных деньгах на {x}: держите наличные в банке и платите из них ежемесячно.",
  "Cash is cheaper in real money by {x}, even after what the bank would pay you.": "Наличные дешевле в реальных деньгах на {x}, даже с учётом того, что заплатил бы банк.",
  "Cash and installments cost about the same in real money.": "Наличные и рассрочка в реальных деньгах стоят примерно одинаково.",
  "Your bank pays a year": "Ваш банк платит в год",
  "Who keeps their word": "Кто держит слово",
