  "Needed from now: {x} a month": "Нужно с этого момента: {x} в месяц",
  "Mission started — Attune works on it every day": "Миссия начата — Attune работает над ней каждый день",
  "Say a goal with a deadline. Attune works on it every day: it reads your money, food and Scout ads, gives your real chance, and the one step for today.": "Назовите цель со сроком. Attune работает над ней каждый день: смотрит ваши деньги, еду и объявления Scout, показывает реальный шанс и один шаг на сегодня.",
  "e.g. «عايز أوفر 60 ألف قبل يونيو»": "например «عايز أوفر 60 ألف قبل يونيو»",
  "Save {t}": "Накопить {t}",
  "Lose {t} kg": "Сбросить {t} кг",
  "Buy it for {t} or less": "Купить за {t} или дешевле",
  "by {d}": "к {d}",
  "add a date (e.g. by June)": "добавьте дату (например, к июню)",
  "Say a number and a date: save 60,000 by June · lose 6 kg before 20 January · buy … under 900k by 1 December · spend no more than 3,000 on food this month · pay off Ahmed's debt by December · finish the Turkish course by December.": "Назовите число и дату: накопить 60 000 к июню · сбросить 6 кг до 20 января · купить … дешевле 900 тыс. к 1 декабря · тратить на еду не больше 3000 в этом месяце · погасить долг Ахмеду к декабрю · закончить курс турецкого к декабрю.",
  "Start the mission": "Начать миссию",
  "Your money missions need {a} a month together, but you keep about {b}. Pause one, or move a date.": "Вашим денежным миссиям вместе нужно {a} в месяц, а вы откладываете около {b}. Поставьте одну на паузу или сдвиньте дату.",
  "No missions yet. Start one above — a saving goal, a weight goal, something to buy, a spending limit, a debt or a course.": "Миссий пока нет. Начните выше — цель накоплений, цель по весу, покупку, лимит трат, долг или курс.",
  "A goal with a date — Attune works on it every day": "Цель с датой — Attune работает над ней каждый день",
  "{c}% chance": "Шанс {c}%",
  "A goal with a date — Attune works on it every day and shows your real chance": "Цель с датой — Attune работает над ней каждый день и показывает реальный шанс",
  "Where": "Где",
  "Every tool in three steps, with a drawing of its screen — and a plan to make Attune part of your day.": "Каждый инструмент в трёх шагах, с рисунком его экрана — и план, как сделать Attune частью вашего дня.",
  "Sync": "Синхронизация",
  "Backup & sync": "Резервная копия и синхронизация",
  "Synced — {a} new, {c} updated. Reopening…": "Синхронизировано — новых: {a}, обновлено: {c}. Перезапуск…",
  "Waiting for the other device…": "Жду другое устройство…",
  "Merging…": "Объединяю…",
  "Locking and sending…": "Шифрую и отправляю…",
  "Signing in to Google…": "Вход в Google…",
  "Locking and uploading…": "Шифрую и загружаю…",
  "Type the address shown on the other device, like 192.168.1.20:41873": "Введите адрес, показанный на другом устройстве, например 192.168.1.20:41873",
  "The code has 8 letters and numbers": "Код состоит из 8 букв и цифр",
  "Set your sync passphrase first — the same on every device.": "Сначала задайте пароль синхронизации — одинаковый на всех устройствах.",
  "Keep your phone and computer (or two phones) the same. The data is locked before it leaves this device; what you delete on one is deleted on the other, nothing else is lost.": "Держите телефон и компьютер (или два телефона) одинаковыми. Данные шифруются до того, как покинут устройство; удалённое на одном удаляется на другом, больше ничего не теряется.",
  "Wi-Fi": "Wi-Fi",
  "Google Drive": "Google Drive",
  "Allow Attune to find your other device on this Wi-Fi (Android asks once).": "Разрешите Attune находить ваше другое устройство в этой сети Wi-Fi (Android спросит один раз).",
  "On the other device: Backup → Sync → Wi-Fi → Connect, and type:": "На другом устройстве: Резервная копия → Синхронизация → Wi-Fi → Подключиться, и введите:",
  "not on Wi-Fi": "нет Wi-Fi",
  "Show a code on this device": "Показать код на этом устройстве",
