  "{who} promised this — follow up, or it slips.": "{who} это обещал — напомните, иначе всё сорвётся.",
  "Paint over the person or thing to remove, then tap Remove.": "Закрасьте человека или предмет, который нужно убрать, затем нажмите «Убрать».",
