  "That picture is gone.": "Этой картинки больше нет.",
  "Couldn't open that photo.": "Не удалось открыть это фото.",
  "Log food on {n} more days and your target will follow what your body really does.": "Записывайте еду ещё {n} дн., и ваша цель будет следовать тому, что реально происходит с вашим телом.",
  "Weigh yourself 2–3 times a week for two weeks and your target will follow what your body really does.": "Взвешивайтесь 2–3 раза в неделю в течение двух недель, и ваша цель будет следовать тому, что реально происходит с вашим телом.",
  "You ate about {eaten} kcal a day and your weight held — so you burn about {burn}. Your plan now counts {tdee}.": "Вы ели около {eaten} ккал в день, и вес держался — значит, вы сжигаете около {burn}. Теперь план считает {tdee}.",
  "You ate about {eaten} kcal a day and lost {kg} kg a week — so you burn about {burn}. Your plan now counts {tdee}.": "Вы ели около {eaten} ккал в день и теряли {kg} кг в неделю — значит, вы сжигаете около {burn}. Теперь план считает {tdee}.",
  "You ate about {eaten} kcal a day and gained {kg} kg a week — so you burn about {burn}. Your plan now counts {tdee}.": "Вы ели около {eaten} ккал в день и набирали {kg} кг в неделю — значит, вы сжигаете около {burn}. Теперь план считает {tdee}.",
  "Remembered about {p}": "Запомнено о {p}",
  "Project brain": "Память проекта",
  "As you chat in this project, what you decide, what is still open and the dates coming up collect here — and the assistant keeps to them.": "Пока вы общаетесь в этом проекте, ваши решения, открытые вопросы и ближайшие даты собираются здесь — и ассистент их придерживается.",
  "Decided": "Решено",
  "Still open": "Ещё открыто",
  "Test a big decision": "Проверить крупное решение",
  "Cash or installments, a new flat, a second car — see 2,000 futures from your own money before you decide.": "Наличные или рассрочка, новая квартира, вторая машина — посмотрите 2000 вариантов будущего на основе ваших денег, прежде чем решать.",
  "Option name": "Название варианта",
  "Pay now": "Заплатить сейчас",
  "Then every month": "Затем каждый месяц",
  "For months": "Сколько месяцев",
  "What you get is worth": "Стоимость того, что вы получите",
  "Inflation": "Инфляция",
  "Bank certificate": "Банковский сертификат",
  "Run the futures": "Просчитать будущее",
  "The simulator needs at least a month of your income and spending in Money.": "Симулятору нужен хотя бы месяц ваших доходов и расходов в «Деньгах».",
  "Option": "Вариант",
  "Never runs out": "Деньги не кончаются",
  "Cash in 1 year": "Наличные через 1 год",
  "3 years": "3 года",
