  "Owned after 5 years": "В собственности через 5 лет",
  "Don't do it": "Не делайте этого",
  "Stress tests: chance cash never runs out": "Стресс-тесты: шанс, что деньги не кончатся",
  "Median of 2,000 futures in today's {c}, from your last {d} days in Money. Installments are fixed, so inflation makes them smaller each month; savings earn the certificate rate. A model, not a promise.": "Медиана 2000 вариантов будущего в сегодняшних {c}, по вашим последним {d} дн. в «Деньгах». Платежи по рассрочке фиксированы, поэтому инфляция каждый месяц их уменьшает; сбережения приносят процент по сертификату. Это модель, а не обещание.",
  "Careful: with every option, your cash runs out in more than 1 future in 10. The safest is {best} ({ok}% of futures stay above zero).": "Осторожно: при любом варианте деньги кончаются больше чем в 1 случае из 10. Самый безопасный — {best} ({ok}% вариантов остаются выше нуля).",
  "{best}: {ok}% of futures never run out of cash; after 5 years you would have about {worth} (today's pounds, including what you bought).": "{best}: в {ok}% вариантов деньги не кончаются; через 5 лет у вас будет около {worth} (в сегодняшних фунтах, включая купленное).",
  "{best} is better: {ok}% of futures never run out of cash, and after 5 years you would have about {worth} in today's pounds — {diff} more than {other}.": "{best} лучше: в {ok}% вариантов деньги не кончаются, а через 5 лет у вас будет около {worth} в сегодняшних фунтах — на {diff} больше, чем {other}.",
  "The answer came in English — writing it again in Arabic…": "Ответ пришёл на английском — переписываю на арабском…",
