  "Message alerts": "Оповещения о сообщениях",
  "Tell Attune whose message you are waiting for — on WhatsApp, Gmail or any email app — and it tells you the moment it arrives. Checked on this phone; SMS only if you switch it on below.": "Скажите Attune, чьего сообщения вы ждёте — в WhatsApp, Gmail или любом почтовом приложении, — и он сообщит, как только оно придёт. Проверяется на этом телефоне; SMS — только если включите ниже.",
  "Turn on Notification access for Attune so it can see new messages (Settings opens). If it is grey, see “restricted setting” in Money → Payments.": "Включите для Attune доступ к уведомлениям, чтобы он видел новые сообщения (откроются настройки). Если переключатель серый, см. «ограниченная настройка» в Деньги → Платежи.",
