  "Choose “Include media” (with the photos)": "Выберите «Добавить медиафайлы» (с фото)",
  "Choose Attune — it reads everything on this phone and sorts it into albums": "Выберите Attune — он прочитает всё на этом телефоне и разложит по альбомам",
  "Export again any time — only what's new is added.": "Экспортируйте снова в любой момент — добавится только новое.",
  "Or pick the exported file": "Или выберите выгруженный файл",
