  "Added to {g}": "Добавлено в {g}",
  "Add photos or a note": "Добавить фото или заметку",
  "New group in Attune": "Новая группа в Attune",
  "One photo or message: share it from WhatsApp or the gallery to “Attune · Groups”.": "Одно фото или сообщение: поделитесь им из WhatsApp или галереи в «Attune · Группы».",
  "Add to a group": "Добавить в группу",
