  "{n} photos chosen": "Выбрано фото: {n}",
  "Choose photos": "Выбрать фото",
  "A note or a link (optional) — “grey sofa for the reception”": "Заметка или ссылка (необязательно) — «серый диван для гостиной»",
  "Album": "Альбом",
  "Let Attune sort it": "Пусть Attune разложит",
  "Couldn't read that file — pick the .xml the SMS backup app made.": "Не удалось прочитать файл — выберите .xml, созданный приложением для копий SMS.",
  "No bank or wallet messages from the last year in that file.": "В этом файле нет сообщений банков или кошельков за последний год.",
  "From Google Play, install a free SMS backup app — e.g. “SMS Backup & Restore”.": "Установите из Google Play бесплатное приложение для копий SMS — например, «SMS Backup & Restore».",
  "Open it → Back up → only Messages → save on this phone (Downloads).": "Откройте его → Резервная копия → только «Сообщения» → сохраните на этом телефоне (Загрузки).",
  "Come back here and pick the backup file (.xml).": "Вернитесь сюда и выберите файл копии (.xml).",
  "Pick the SMS backup file": "Выбрать файл копии SMS",
  "How?": "Как?",
  "Attune doesn't ask for SMS access (Google blocks apps installed from a file that do) — it reads the backup file instead.": "Attune не запрашивает доступ к SMS (Google блокирует такие приложения, установленные из файла) — вместо этого он читает файл копии.",
  "Nothing had all your words — the closest:": "Ни в чём не нашлось всех ваших слов — ближайшее:",
  "Nothing to search yet — add screenshots or keep your notifications below": "Искать пока не в чем — добавьте скриншоты или сохраняйте уведомления ниже",
  "Add screenshots and photos": "Добавить скриншоты и фото",
  "Their text is read on the phone, so “the receipt from Carrefour” finds them. They are kept in Mind.": "Их текст читается на телефоне, поэтому «чек из Carrefour» их найдёт. Они хранятся в Mind.",
  "Keep my notifications for 30 days": "Хранить мои уведомления 30 дней",
  "WhatsApp, SMS, email, deliveries, banks — so you can find what someone sent. Never one-time codes. Turning it off forgets them.": "WhatsApp, SMS, почта, доставки, банки — чтобы найти, что кто-то прислал. Никаких одноразовых кодов. Если выключить — они забудутся.",
  "Needs Notification access (the same switch as Money).": "Нужен доступ к уведомлениям (тот же переключатель, что и для «Денег»).",
  "Everything stays on this phone.": "Всё остаётся на этом телефоне.",
  "Screenshots & photos": "Скриншоты и фото",
  "Notifications": "Уведомления",
  "Saved pages": "Сохранённые страницы",
  "The phone is warm — stopped early so it cools": "Телефон нагрелся — остановлено раньше, чтобы он остыл",
  "Timing {a} of {b}…": "Замер {a} из {b}…",
  "Fastest on this phone: {g} threads — {t} tokens/s": "Быстрее всего на этом телефоне: {g} потоков — {t} токенов/с",
  "Couldn't time the model — nothing changed": "Не удалось замерить модель — ничего не изменено",
  "Tune for this phone": "Настроить под этот телефон",
  "Tuned: {g} threads, {t} tokens/s": "Настроено: {g} потоков, {t} токенов/с",
  "Looking…": "Ищу…",
  "Cheapest price": "Самая низкая цена",
  "Prices from the web — check at the pharmacy; the same box size matters.": "Цены из интернета — уточните в аптеке; важен одинаковый размер упаковки.",
  "No price found online": "Цену в интернете не нашли",
  "One result so far — the next report shows the trend.": "Пока один результат — следующий анализ покажет динамику.",
  "{n} results in {y} years: {a} → {b} {u} ({c}).": "Результатов: {n} за {y} г.: {a} → {b} {u} ({c}).",
  "Outside the report's range {k} times.": "Выходило за норму анализа {k} раз.",
  "Show this to your doctor — the trend says more than one result.": "Покажите это врачу — динамика говорит больше, чем один результат.",
  "Your watch's temperature rose {r} °C: ovulation around {o}, so the period is expected {n}.": "Температура по часам поднялась на {r} °C: овуляция около {o}, поэтому месячные ожидаются {n}.",
  "(your own {d} days after ovulation)": "(ваши собственные {d} дн. после овуляции)",
  "(14 days after ovulation until 2 cycles are measured)": "(14 дней после овуляции, пока не измерены 2 цикла)",
  "No temperature rise yet — ovulation looks later than usual, so the period will likely be later than the date above.": "Подъёма температуры пока нет — овуляция, похоже, позже обычного, так что месячные, скорее всего, будут позже указанной даты.",
  "{n} nights of temperature from your watch — the rise after ovulation shows here.": "Ночей с температурой с ваших часов: {n} — подъём после овуляции виден здесь.",
  "A watch that measures night temperature (Galaxy Watch, Pixel Watch, Oura…) makes the prediction more exact.": "Часы, измеряющие ночную температуру (Galaxy Watch, Pixel Watch, Oura…), делают прогноз точнее.",
  "Use my watch's temperature": "Использовать температуру с моих часов",
