  "Automations": "Автоматизации",
  "Say what should happen — “when my salary arrives, put 20% in the car fund” — and it runs by itself": "Скажите, что должно происходить — «когда придёт зарплата, отложи 20% в фонд на машину», — и это будет выполняться само",
  "Say what should happen": "Скажите, что должно происходить",
  "e.g. When my salary arrives, put 20% in the car fund and tell me": "напр.: Когда придёт зарплата, отложи 20% в фонд на машину и сообщи мне",
  "I didn't get that as an automation. Try: When my salary arrives, put 20% in the car fund.": "Не получилось понять это как автоматизацию. Попробуйте: Когда придёт зарплата, отложи 20% в фонд на машину.",
  "Automation on — it runs on the phone, no AI needed": "Автоматизация включена — работает на телефоне, без ИИ",
