  "Your phone's own offline speech recogniser listens to the video, piece by piece — the sound never leaves the phone. About as long as the video.": "Офлайн-распознаватель речи вашего телефона слушает видео по частям — звук не покидает телефон. Примерно столько же, сколько длится видео.",
  "Subtitles need Android 13 or newer": "Для субтитров нужен Android 13 или новее",
  "Google sync on the computer needs one setup step by Attune's owner (its Google client) — use Wi-Fi with your phone until then.": "Синхронизации с Google на компьютере нужен один шаг настройки от владельца Attune (его клиент Google) — до тех пор используйте Wi-Fi с телефоном.",
  "The first time, Google's sign-in page opens in your browser; after that the computer stays signed in.": "В первый раз страница входа Google откроется в браузере; после этого компьютер останется в аккаунте.",
