  "Your details — bookings and better answers": "Ваши данные — для бронирований и более точных ответов",
  "Private: everything here stays on this phone — Attune never uploads it, and its AI runs on the phone. Answers and agents use only your trip and daily-life details (never your passport, phone or email). A booking site gets your name, passport and phone only when you tap “Fill my details”.": "Приватно: всё здесь остаётся на этом телефоне — Attune никогда это не загружает, а его ИИ работает на телефоне. Ответы и агенты используют только данные о поездках и повседневной жизни (никогда паспорт, телефон или почту). Сайт бронирования получает ваше имя, паспорт и телефон только когда вы нажимаете «Заполнить мои данные».",
  "Use my details to make answers and agents fit me": "Учитывать мои данные в ответах и агентах",
  "Trips and hotels": "Поездки и отели",
  "Agents use these when your sentence doesn't say — e.g. a hotel watch looks for your stars by itself.": "Агенты используют это, когда в вашей фразе не сказано, — например, слежение за отелем само ищет вашу звёздность.",
  "Daily life": "Повседневная жизнь",
  "So Chat's answers fit you: food, health, your car, your work.": "Чтобы ответы в чате подходили вам: еда, здоровье, ваша машина, ваша работа.",
  "For booking forms": "Для форм бронирования",
  "Typed into a booking site only when you tap “Fill my details”. Never used in answers.": "Вписывается на сайт бронирования, только когда вы нажимаете «Заполнить мои данные». В ответах не используется.",
