  "Payment pending — Pro turns on by itself as soon as Google confirms it.": "Платёж в обработке — Pro включится сам, как только Google подтвердит.",
  "Google Play: {e}": "Google Play: {e}",
  "SHA-256": "SHA-256",
  "owner/repo:QUANT": "owner/repo:QUANT",
  "With more than one model installed: quick questions use the one already running; code, maths, reasoning and long reports move to your strongest model that runs smoothly here, and photos to one that sees. A switch takes 10–30 s.": "Если установлено несколько моделей: быстрые вопросы отвечает уже запущенная; код, математика, рассуждения и длинные отчёты переходят к самой сильной модели, которая здесь работает плавно, а фото — к той, что видит. Переключение занимает 10–30 с.",
  "The model itself never uses the network. The log lists every connection the app made or refused, host and reason only — the proof behind \\\"nothing leaves this phone\\\".": "Сама модель никогда не использует сеть. Журнал показывает каждое соединение, которое приложение установило или отклонило, — только хост и причину. Это доказательство того, что \\\"ничего не покидает этот телефон\\\".",
  "When my salary arrives, put 20% in Savings": "Когда придёт зарплата, отложи 20% в «Сбережения»",
  "When my salary arrives, put 10% in the Emergency fund": "Когда придёт зарплата, отложи 10% в подушку безопасности",
