  "what exactly will be delivered": "что именно будет поставлено",
  "the price and when it is paid": "цена и когда она платится",
  "the deadline": "срок",
  "Ask for a normal deposit or a bank guarantee instead, and never sign anything blank.": "Попросите вместо этого обычный залог или банковскую гарантию и никогда не подписывайте ничего пустого.",
  "It renews by itself — you keep paying unless you cancel in time.": "Продлевается само — вы платите дальше, если не отмените вовремя.",
  "Ask for renewal only by written agreement, or put the cancel-by date in your Deadline Radar.": "Попросите продление только по письменному согласию или внесите дату, до которой нужно отменить, в Радар сроков.",
  "Only one side can end it, or it can be ended without notice.": "Расторгнуть может только одна сторона, или без уведомления.",
  "Ask that both sides can end it, with the same written notice (e.g. 30 days).": "Попросите, чтобы обе стороны могли расторгнуть с одинаковым письменным уведомлением (например, за 30 дней).",
  "The other side can change the terms or the price on its own.": "Другая сторона может сама менять условия или цену.",
  "Ask that changes need both signatures, and that you can leave without a penalty if you don't accept them.": "Попросите, чтобы изменения требовали подписей обеих сторон и чтобы вы могли выйти без штрафа, если не согласны.",
  "A penalty or forfeit clause — check the amount and that it applies to both sides.": "Пункт о штрафе или неустойке — проверьте сумму и что он действует для обеих сторон.",
  "Ask for a cap (e.g. one month's value) and the same penalty for the other side.": "Попросите потолок (например, стоимость одного месяца) и такой же штраф для другой стороны.",
  "Money you pay here does not come back, even if the deal falls through.": "Деньги, которые вы здесь платите, не возвращаются, даже если сделка сорвётся.",
  "Ask that it is refunded if the other side cancels or doesn't deliver.": "Попросите возврат, если другая сторона отменит или не исполнит.",
  "You carry all the risk, with no limit.": "Весь риск на вас, без ограничений.",
  "Ask for a limit (e.g. the contract's value) and to exclude what you can't control.": "Попросите лимит (например, сумму договора) и исключение того, что вы не контролируете.",
  "You may not work for a competitor after you leave — check how long and where.": "После ухода нельзя работать на конкурента — проверьте, как долго и где.",
  "Ask for 6–12 months at most, one city or field, and pay for the time it applies.": "Попросите не больше 6–12 месяцев, один город или сфера, и оплату за это время.",
  "Everything you make — even in your own time — would belong to them.": "Всё, что вы создаёте, — даже в личное время — будет принадлежать им.",
  "Ask to limit it to work done for them, in work time, with their tools.": "Попросите ограничить это работой для них, в рабочее время и их инструментами.",
  "Disputes go to arbitration or to another country's courts — this can be slow and expensive for you.": "Споры идут в арбитраж или в суды другой страны — это может быть долго и дорого для вас.",
  "Ask for the courts of your own city.": "Попросите суды вашего города.",
  "You give up a right (to sue, to a refund, to object).": "Вы отказываетесь от права (подать в суд, на возврат, возразить).",
  "Ask to delete the waiver.": "Попросите удалить этот отказ.",
  "Sold as it is, with no guarantee — problems found later are yours.": "Продаётся как есть, без гарантии — проблемы, найденные позже, ваши.",
  "Inspect it first (with an expert), or ask for a written guarantee period.": "Сначала осмотрите (со специалистом) или попросите письменный гарантийный срок.",
  "Secrecy that never ends.": "Бессрочная конфиденциальность.",
