  "US Navy method: waist at the navel (women: narrowest), neck below the Adam's apple — ±3 %. The trend matters more than one number.": "Метод ВМС США: талия на уровне пупка (у женщин — самое узкое место), шея под кадыком — ±3 %. Тренд важнее одного числа.",
