  "No closed year yet — when you finish paying a year's Zakāt, close it here and keep its certificate.": "Закрытых лет пока нет — когда выплатите закят за год, закройте его здесь и сохраните сертификат.",
  "An estimate to guide you. It uses the gold nisab (85g) and 2.5% on cash, gold, silver and money owed to you — not your home, car, or work equipment. Rulings on debts and on dropping below nisab during the year differ between scholars; confirm your case with a trusted scholar.": "Ориентировочная оценка. Используется нисаб золота (85 г) и 2,5% с наличных, золота, серебра и денег, которые вам должны, — не с дома, машины или рабочего оборудования. Мнения учёных о долгах и о снижении ниже нисаба в течение года расходятся; уточните свой случай у надёжного учёного.",
